"""Explain derived arithmetic tests and native-word acquire/release fallbacks."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1613': ('“한 개 늘리기”는 “1 더하기”로 만들 수 있어요. 이미 있는 도구를 같은 뜻으로 연결하면 새 기능의 코드를 반복해서 적지 않아도 돼요.', 'inc·dec·andnot이 기존 연산을 재사용하는 방법을 이해합니다.', 'inc → add(1), dec → sub(1), andnot(i) → and(~i)를 적으세요. 7의 아래 세 비트 111에서 2의 자리만 끄면 101=5예요.', ['inc는 1 증가, dec는 1 감소예요. inc 양식은 add에 증가량 1과 대상 v를 전달하고, dec 양식은 sub에 감소량 1과 v를 전달해요. 대상의 현재 숫자 전체를 증가량으로 넘기는 것이 아니에요.', '함수 이름의 앞부분 pfx와 뒷부분 sfx, 순서 이름 order는 그대로 이어 붙여요. 그래서 inc_return은 add_return(1, v)로, fetch_inc_release는 fetch_add_release(1, v)로 연결할 수 있어요.', 'return은 이 계열에서 계산 뒤 값, fetch는 계산 전 값을 반환하는 형태예요. 기존 연산을 재사용하면서도 어떤 값을 돌려주는지와 어떤 순서를 보장하는지를 유지해야 해요.', 'andnot은 마스크 i가 고른 비트를 끄는 연산이에요. AND 기호 &는 둘 다 1인 자리만 남기고, NOT 기호 ~는 비트를 뒤집어요. 그래서 기반 and에 i 그대로가 아니라 ~i를 전달해요.', '예를 들어 7은 아래 세 자리가 111이고 2는 010이에요. 7 & ~2의 아래 세 자리는 101=5예요. 실제 정수는 더 많은 비트를 가지지만 높은 0자리도 AND 뒤 0이라 이 결과는 같아요.', 'fetch_andnot은 기반 fetch_and가 주는 이전 값을 그대로 반환해요. 시작 7이면 저장 5·반환 7이에요. void 형태는 반환문이 필요 없고, 값을 돌려주는 형태에는 생성기가 return을 붙여요. 생성된 호출 이름과 인자를 함께 확인하세요.'], [('inc를 add로 만들 때 더할 수는 무엇인가요?', ['현재 counter 전체 값이에요', '1이에요'], '정답은 두 번째예요. inc는 언제나 1 증가라는 뜻이라 양식이 인자 1을 적어요. 반환 방식과 순서 꼬리표는 해당 형태에 맞춰 유지해요.'), ('andnot(i)를 and로 만들 때 넘기는 마스크는 무엇인가요?', ['i의 비트를 뒤집은 ~i예요', '뒤집지 않은 i예요'], '정답은 첫 번째예요. ~i와 AND해야 i에서 1인 자리를 끌 수 있어요. 111 & 010은 2지만 111 & ~010의 아래 세 자리는 5이므로 둘은 달라요.')]), 'os1614': ('계산한 뒤 “0인가요?”라고 묻는 것과 계산하기 전에 “0이면 건너뛸까요?”라고 묻는 것은 달라요. 이름이 비슷해도 질문의 시점을 나누어 보세요.', '결과 검사 함수와 조건부 증가 함수의 차이를 이해합니다.', 'inc_and_test: -1→0·true, 0→1·false와 inc_not_zero: 0 유지·false를 나란히 적으세요.', ['검사형 API는 숫자 자체 대신 참·거짓을 반환해요. 하지만 어떤 질문의 답인지가 함수마다 달라요. bool이라는 같은 자료형을 쓴다고 모두 “계산 성공”을 뜻하는 것은 아니에요.', 'sub_and_test는 sub_return(i, v)의 결과가 0인지 비교해요. sub_return은 갱신 뒤 값을 돌려주므로 시작 3에서 3을 빼면 저장 0·true, 2를 빼면 저장 1·false예요. false여도 뺄셈은 했어요.', 'dec_and_test와 inc_and_test도 해당 return 연산의 결과를 0과 비교해요. -1에서 inc_and_test를 하면 0을 저장하고 true예요. 0에서 하면 1을 저장하고 false예요.', 'add_negative는 add_return의 결과가 0보다 작은지 확인해요. -3에 1을 더하면 -2라 true, -1에 1을 더하면 0이라 false예요. 0은 음수가 아니에요.', 'inc_not_zero는 add_unless(v, 1, 0)를 호출해요. 0이면 건너뛰고 false, 0이 아니면 1을 더하고 true를 받아요. 계산 뒤 0 검사와 달리 계산할지부터 조건으로 정하는 함수예요.', '이런 조합에서 조건 검사는 기반 원자 연산이 돌려준 값에 적용돼요. 별도로 숫자판을 다시 읽어 검사하는 것이 아니에요. 또한 true나 0을 봤다고 자료를 지워도 된다는 권한까지 생기지는 않으므로 수명 규칙은 따로 필요해요.'], [('inc_not_zero는 어떤 기반 연산을 사용하나요?', ['무조건 add_return으로 1을 더하고 양수인지 봐요', '금지 값 0을 둔 add_unless(v, 1, 0)를 사용해요'], '정답은 두 번째예요. 시작 0이면 더하지 않는 기능이 필요해요. 먼저 무조건 더한 뒤 결과를 검사하는 방법과 동작이 달라요.'), ('sub_and_test는 무엇을 검사하나요?', ['뺄셈 뒤 값이 0인지 검사해요', '언제나 뺄셈 전 값이 양수인지 검사해요'], '정답은 첫 번째예요. 식은 sub_return(i, v) == 0이에요. sub_return이 알려 주는 갱신 뒤 숫자에 조건을 적용해요.')]), 'os1615': ('한 번에 다룰 수 있는 크기의 상자와 더 큰 상자는 옮기는 방법이 다를 수 있어요. 읽기 코드도 타입 크기 조건을 보고 알맞은 경로를 선택해요.', 'native word 조건에 따른 acquire 읽기의 두 경로를 이해합니다.', 'native 조건 참 → smp_load_acquire, 거짓 → raw read → acquire fence → 반환의 두 줄을 그리세요.', ['word는 CPU가 기본적으로 다루는 데이터 크기를 설명할 때 쓰는 말이에요. 여기서는 __native_word라는 코드의 타입 크기 조건이 기준이에요. 특정 컴퓨터의 크기를 모든 CPU의 공통 크기로 외우지 마세요.', 'read_acquire 양식은 __native_word(원자타입)를 검사해요. 참인 갈래는 대상의 counter에 smp_load_acquire를 사용해 읽은 값을 ret에 담아요. 읽기와 acquire 순서 약속을 이 도구로 제공하는 경로예요.', '거짓인 갈래는 raw 원자 read로 값을 ret에 담고, 그 뒤 __atomic_acquire_fence를 실행해요. 마지막에 ret를 반환해요. 읽기의 원자성을 기반 함수에 맡기고 추가 순서를 뒤에서 보강해요.', '큰 자료를 부분적으로 두 번 읽어 합치면 사이에 다른 갱신이 끼어 새 조각과 옛 조각이 섞일 수 있어요. 그래서 이 갈래를 “아무 일반 읽기나 두 번 해도 된다”는 뜻으로 바꾸어 읽으면 안 돼요. 실제 raw read의 보장이 중요해요.', '장벽은 다른 메모리 접근에 필요한 순서를 보강해요. 이미 읽은 값을 영원히 최신으로 고정하거나 자료의 수명을 늘리는 장치는 아니에요. 반환 ret는 그 연산에서 얻은 값이에요.', '연습 모델에서 크기 조건을 참·거짓으로 바꾸어 경로를 확인할 수는 있어요. 하지만 그것은 해당 CPU에서 넓은 원자 읽기를 실제 실행한 증거가 아니에요. 타입 크기, ABI, 하드웨어 동작의 확인 범위를 나누어 보세요.'], [('native word 조건이 거짓인 읽기 갈래의 순서는 무엇인가요?', ['일반 부분 읽기 두 번을 하고 값을 합쳐요', 'raw 원자 read를 한 뒤 acquire fence를 실행해요'], '정답은 두 번째예요. 먼저 raw read로 ret를 얻고 뒤 장벽을 거쳐 반환해요. 기반 원자 읽기를 일반 부분 읽기로 바꾸면 같은 약속이 아니에요.'), ('모델에서 조건을 거짓으로 넣어 갈래를 확인하면 실제 넓은 자료형 CPU의 실행 검증인가요?', ['아니요. 그 모델에서 선택된 호출 구조를 확인한 것이에요', '네. 조건 하나를 바꾸면 모든 CPU를 실행한 셈이에요'], '정답은 첫 번째예요. 갈래 선택 검사와 실제 CPU·자료형 환경의 실행은 다른 증거예요. 모델이 확인한 범위를 넘겨 말하면 안 돼요.')]), 'os1616': ('“내용을 먼저 준비하고 완료 표시를 붙이기”에서는 표시를 쓰기 전에 순서를 지켜야 해요. 읽기 뒤에 붙이는 acquire 장벽과 저장 앞의 release 장벽을 비교해 봅시다.', 'release 저장의 두 경로와 경쟁 갱신의 원자성 유지 조건을 이해합니다.', 'native 조건 참 → smp_store_release, 거짓 → release fence → raw set의 두 경로를 적으세요.', ['set_release는 정한 숫자를 저장하면서 앞선 접근과의 release 순서를 제공하는 연산이에요. release는 앞서 한 메모리 접근이 이 저장 뒤로 넘어가지 않도록 하는 방향의 약속이에요.', '양식은 __native_word(원자타입)가 참이면 smp_store_release로 counter에 i를 저장해요. 타입 조건과 해당 아키텍처의 도구를 사용하는 갈래예요. 호출자가 아무 주소에 직접 저장해도 된다는 일반 허가는 아니에요.', '조건이 거짓이면 __atomic_release_fence를 먼저 실행하고 raw 원자 set으로 i를 저장해요. acquire 읽기의 raw read → 뒤 장벽과 반대로 저장 전 장벽이에요.', '여기서 raw set은 같은 대상에 경쟁하는 원자 RMW를 깨지 않아야 해요. RMW는 값을 읽고 바꾸어 쓰는 한 연산이에요. 넓은 값의 일부만 먼저 바뀌거나 보호를 우회하면 기반 API의 약속을 잃을 수 있어요.', '예를 들어 잠금으로 보호하는 기반 구현이라면 set도 그 원자성에 맞는 보호 방법을 따라야 해요. fallback으로 만들어졌다는 이유만으로 일반 직접 대입을 섞어도 되는 것은 아니에요.', '순서 장벽 위치를 읽는 검사와 실제 CPU의 저장·캐시 동작 검증은 구별해야 해요. 또한 release 저장만으로 읽는 쪽의 모든 조건이 완성되지는 않아요. 데이터를 공개하는 경우 대응하는 읽기 규칙과 자료 수명도 함께 정해야 해요.'], [('native word 조건이 거짓인 set_release의 순서는 무엇인가요?', ['raw set을 먼저 하고 acquire fence를 붙여요', 'release fence를 먼저 하고 raw set을 해요'], '정답은 두 번째예요. 앞선 접근의 순서를 저장 전에 보강하는 구조예요. 읽기 뒤 acquire 장벽을 두는 경로와 방향을 구별하세요.'), ('fallback set도 함께 경쟁하는 RMW의 원자성 약속을 지켜야 하나요?', ['네. 대체 경로에서도 원자성 보호는 유지돼야 해요', '아니요. fallback이면 어떤 직접 대입도 허용돼요'], '정답은 첫 번째예요. 구현 경로가 달라져도 API의 약속은 사라지지 않아요. 앞에 장벽이 있다는 이유로 기반 set의 보호를 우회하면 안 돼요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_399.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
